import{z as s,x as A,o,c as n,q as d,j as c,D as a,d as r,s as t,S as B}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"聚合与 GROUP BY","description":"","frontmatter":{"title":"聚合与 GROUP BY","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sql-aggregation.md","filePath":"cs/sql-aggregation.md","lastUpdated":1791413859000}'),l={name:"cs/sql-aggregation.md"};function i(p,e,m,C,R,h){const E=A("Mermaid");return o(),n("div",null,[e[2]||(e[2]=d('<h1 id="聚合与-group-by" tabindex="-1">聚合与 GROUP BY <a class="header-anchor" href="#聚合与-group-by" aria-label="Permalink to &quot;聚合与 GROUP BY&quot;">​</a></h1><div class="epigraph"><p>分组把包切成等价类，聚合把每一类收成一行标量；结果仍是关系，只是属性不再是输入列的简单子集。</p><footer>—— 据 Chamberlin and Boyce, SEQUEL, 1974；SQL 标准对 GROUP BY；Ramakrishnan and Gehrke 对聚合算子的整理</footer></div><p><a href="/cs/sharding">上一课</a>把库水平切开：片内事务，片间要 2PC 或弱化，复制与分片正交。本课打开查询语言进阶：主干 <a href="/cs/sql-declarative">SQL 声明</a> 已把 <code>SELECT</code>–<code>FROM</code>–<code>WHERE</code> 钉在代数上，并点名分组「把元组集收成组上的标量」，但没有机制。缺口不是重讲投影，而是 <strong>GROUP BY 如何改变结果模式</strong>，以及 <code>HAVING</code> 与 <code>WHERE</code> 为何不能互换。不重写 Transformer，不进限价簿。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>声明课把查询收成代数树。连接与选择之后，用户仍要「每个顾客多少订单」「每个月合计」。若应用拉回全部行再自己加，等于放弃声明性，优化器看不见分组。缺口是语言里的分组算子：按一组列划等价类，每组产出一行；<code>COUNT</code>/<code>SUM</code>/<code>AVG</code>/<code>MIN</code>/<code>MAX</code> 是组上的函数，不是行上的投影。</p><p><code>WHERE</code> 在分组前滤行；<code>HAVING</code> 在分组后滤组。把聚合写进 <code>WHERE</code> 没有指称。未分组查询里的裸聚合把整张输入当成一组。<code>SELECT</code> 列表在有 <code>GROUP BY</code> 时只能出现分组列或聚合——否则一行组无法决定「其余列取哪一个值」。</p><p><span class="marginnote">SQL 默认包：同一组里重复行计入 <code>COUNT(*)</code>。<code>COUNT(col)</code> 不计该列上的 NULL。<code>SUM</code> 全 NULL 组得 NULL 不是 0。三值逻辑仍是 <a href="/cs/sql-null">空值</a> 那一套，本课不重推。</span></p><p><span class="marginnote">数字实例：订单表里顾客 A 有 3 单（金额 10、20、30），<code>SELECT cust, SUM(amt) FROM orders GROUP BY cust</code> 产出 <code>(A, 60)</code> 一行——金额列的 3 个值被收成 1 个标量，而 <code>SUM</code> 前先用 <code>WHERE amt \\gt 15</code> 滤行就只剩 <code>(A, 50)</code>。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>逻辑上看，分组是 \\(\\gamma_{G,A}(R)\\)：按 \\(G\\) 分组，算聚合列表 \\(A\\)，输出模式是 \\(G\\) 加上各聚合的结果列。物理实现可以排序后扫描相邻组，或哈希建桶——算子形状后课 <a href="/cs/hash-aggregation">哈希聚合</a> 才写；本课只要求语义先钉住。</p><p><code>DISTINCT</code> 聚合（<code>COUNT(DISTINCT x)</code>）先在组内去重再聚合。过滤聚合（<code>FILTER (WHERE …)</code>）是组内再选，不等于外层 <code>WHERE</code>。本课不把每个方言的 <code>GROUPING SETS</code> 当必会语法，只点名：同一输入上多个分组集是多个 \\(\\gamma\\) 的并。</p>',11)),(o(),c(B,null,{default:a(()=>[t(E,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E8%BE%93%E5%85%A5%E5%8C%85%22%5D%20--%3E%20WHERE%5B%22WHERE%20%E6%BB%A4%E8%A1%8C%22%5D%0A%20%20WHERE%20--%3E%20GRP%5B%22%E6%8C%89%20G%20%E5%88%92%E7%BB%84%22%5D%0A%20%20GRP%20--%3E%20AGG%5B%22%E7%BB%84%E4%B8%8A%E8%81%9A%E5%90%88%22%5D%0A%20%20AGG%20--%3E%20HAV%5B%22HAVING%20%E6%BB%A4%E7%BB%84%22%5D%0A%20%20HAV%20--%3E%20OUT%5B%22%E7%BB%93%E6%9E%9C%E5%85%B3%E7%B3%BB%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=d('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分组挡住若干代数律：不能把组后谓词随便推到组前，除非谓词只谈 \\(G\\) 且不含聚合。连接与分组的交换要看键：若连接键是分组键的超集，有时可先聚后连以缩小输入——这是改写，不是改语义。优化器后课会搜这些形状；本课只承认分组是改写防火墙之一，与 <a href="/cs/query-rewrite">查询改写</a> 点名的窗口、极限同类。</p><p>空组：<code>FROM</code> 为空时，无 <code>GROUP BY</code> 的裸聚合仍产出一行（<code>COUNT(*)</code> 为 0）；有 <code>GROUP BY</code> 则零行。这是标准里的坑，声明含义必须包含它，否则「有没有分组」会改结果基数。</p>',3)),(o(),c(B,null,{default:a(()=>[t(E,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%BE%93%E5%85%A5%E4%B8%BA%E7%A9%BA%EF%BC%880%20%E8%A1%8C%EF%BC%89%22%5D%20--%3E%20B%7B%22%E6%9C%89%E6%B2%A1%E6%9C%89%20GROUP%20BY%EF%BC%9F%22%7D%0A%20%20B%20--%3E%7C%22%E6%B2%A1%E6%9C%89%3A%20%E6%95%B4%E8%A1%A8%E8%A7%86%E4%B8%BA%E4%B8%80%E7%BB%84%22%7C%20R1%5B%22%E4%BB%8D%E4%BA%A7%E5%87%BA%E4%B8%80%E8%A1%8C%3Cbr%2F%3ECOUNT(*)%3D0%2C%20SUM%3DNULL%22%5D%0A%20%20B%20--%3E%7C%22%E6%9C%89%3A%20%E6%8C%89%20G%20%E5%88%92%E7%AD%89%E4%BB%B7%E7%B1%BB%22%7C%20R2%5B%22%E4%B8%80%E4%B8%AA%E7%BB%84%E9%83%BD%E5%88%92%E4%B8%8D%E5%87%BA%E6%9D%A5%3Cbr%2F%3E%E7%BB%93%E6%9E%9C%E6%98%AF%200%20%E8%A1%8C%22%5D%0A%20%20R1%20--%3E%20USE%5B%22%E4%B8%8B%E6%B8%B8%3A%20INSERT%20%E9%80%89%E5%93%AA%E4%B8%AA%3F%20%E6%8A%A5%E8%A1%A8%E6%98%BE%E7%A4%BA%E5%87%A0%E8%A1%8C%3F%22%5D%0A%20%20R2%20--%3E%20USE%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=d('<p><span class="marginnote">术语翻译：<code>HAVING</code> 就是「对聚合结果再下条件」——<code>HAVING SUM(amt) \\gt 100</code> 意思是「先按组算出每组的合计，再把合计不到 100 的整组丢掉」；它是组这一层的过滤器，不是行那一层的。</span></p><p><span class="marginnote">常见误区：初学者容易把 <code>WHERE SUM(amt) \\gt 100</code> 直接写上去，实际报错——<code>WHERE</code> 执行时组还没划出来，聚合值不存在。想先滤行写 <code>WHERE amt \\gt 100</code>，想滤组写 <code>HAVING SUM(amt) \\gt 100</code>，两者管的时点不同。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲窗口函数：窗口也聚合，但不把多行收成一行，组的边界与帧不同。子查询里的聚合、相关与否，下一课之后才去相关。也不把 OLAP 立方、<code>CUBE</code>/<code>ROLLUP</code> 的稀疏格写进本课必做。</p><p>存储与索引：分组列上的有序扫描能省排序，那是计划选择，不是 GROUP BY 的定义。后课默认：谈到分组查询，先有 \\(\\gamma\\) 的模式与空组规则；物理是排序或哈希，语义不是循环加器。</p><p>主干连接算法课未改分组语义。进阶从这里把查询语言从「行过滤」接到「组收缩」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><code>GROUP BY</code> 按列划组，聚合把每组收成一行；<code>HAVING</code> 滤组，<code>WHERE</code> 滤行。</li><li>未分组的裸聚合视整表为一组；空输入时与有分组的基数规则不同。</li><li>分组是改写防火墙；窗口函数下一课，形状不同。</li><li>出处：Chamberlin and Boyce；SQL 标准；Ramakrishnan and Gehrke。</li></ul>',8))])}const U=s(l,[["render",i]]);export{T as __pageData,U as default};
